#!/usr/bin/env node

/**
 * Offline Node.js consistency validator for the locally exported BERT ONNX model.
 *
 * This file contains no model weights, training texts, calibration texts, or blind
 * test texts. It receives the private local export folder by CLI path and validates
 * only the intentionally non-evaluation fixture generated by the Python exporter.
 */

import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import * as ort from "onnxruntime-node";

const MAX_ALLOWED_PROBABILITY_DELTA = 0.01;

function getArgument(name) {
  const index = process.argv.indexOf(name);
  return index === -1 ? undefined : process.argv[index + 1];
}

function memorySnapshot() {
  const memory = process.memoryUsage();
  return Object.fromEntries(Object.entries(memory).map(([key, value]) => [key, Math.round(value / 1024 / 1024 * 100) / 100]));
}

function softmaxAiProbability(logits) {
  const maxLogit = Math.max(...logits);
  const exponentials = logits.map((value) => Math.exp(value - maxLogit));
  return exponentials[1] / exponentials.reduce((sum, value) => sum + value, 0);
}

function isWhitespace(character) {
  return /\s/.test(character);
}

function isControl(character) {
  const code = character.codePointAt(0);
  return (code <= 31 || (code >= 127 && code <= 159)) && !isWhitespace(character);
}

function isPunctuation(character) {
  const code = character.codePointAt(0);
  return (code >= 33 && code <= 47) || (code >= 58 && code <= 64) || (code >= 91 && code <= 96) || (code >= 123 && code <= 126) || /[，。！？；：、“”‘’（）《》【】—…]/u.test(character);
}

function isChineseCharacter(character) {
  const code = character.codePointAt(0);
  return (code >= 0x4e00 && code <= 0x9fff) || (code >= 0x3400 && code <= 0x4dbf) || (code >= 0xf900 && code <= 0xfaff);
}

function cleanAndSplit(text, doLowerCase) {
  let cleaned = "";
  for (const character of text.normalize("NFC")) {
    if (character === "\u0000" || character === "\ufffd" || isControl(character)) {
      continue;
    }
    if (isChineseCharacter(character) || isPunctuation(character)) {
      cleaned += ` ${character} `;
    } else if (isWhitespace(character)) {
      cleaned += " ";
    } else {
      cleaned += character;
    }
  }
  return cleaned
    .trim()
    .split(/\s+/u)
    .filter(Boolean)
    .map((token) => doLowerCase ? token.toLowerCase() : token);
}

function wordPiece(token, vocabulary, unknownToken) {
  if (vocabulary.has(token)) {
    return [token];
  }
  const characters = [...token];
  const pieces = [];
  let start = 0;
  while (start < characters.length) {
    let end = characters.length;
    let current;
    while (start < end) {
      const candidate = `${start === 0 ? "" : "##"}${characters.slice(start, end).join("")}`;
      if (vocabulary.has(candidate)) {
        current = candidate;
        break;
      }
      end -= 1;
    }
    if (!current) {
      return [unknownToken];
    }
    pieces.push(current);
    start = end;
  }
  return pieces;
}

function encode(text, tokenizer) {
  const pieces = cleanAndSplit(text, tokenizer.doLowerCase)
    .flatMap((token) => wordPiece(token, tokenizer.vocabulary, tokenizer.unknownToken))
    .slice(0, tokenizer.maxLength - 2);
  const tokens = [tokenizer.clsToken, ...pieces, tokenizer.sepToken];
  const ids = tokens.map((token) => tokenizer.vocabulary.get(token) ?? tokenizer.unknownId);
  const values = BigInt64Array.from(ids, (id) => BigInt(id));
  return new ort.Tensor("int64", values, [1, ids.length]);
}

async function readTokenizer(exportDirectory, maxLength) {
  const [vocabContent, configContent, specialTokensContent] = await Promise.all([
    fs.readFile(path.join(exportDirectory, "vocab.txt"), "utf8"),
    fs.readFile(path.join(exportDirectory, "tokenizer_config.json"), "utf8"),
    fs.readFile(path.join(exportDirectory, "special_tokens_map.json"), "utf8"),
  ]);
  const vocabulary = new Map(vocabContent.split(/\r?\n/u).filter((token) => token.length > 0).map((token, index) => [token, index]));
  const config = JSON.parse(configContent);
  const specialTokens = JSON.parse(specialTokensContent);
  const tokenizer = {
    vocabulary,
    maxLength,
    doLowerCase: Boolean(config.do_lower_case),
    clsToken: specialTokens.cls_token ?? "[CLS]",
    sepToken: specialTokens.sep_token ?? "[SEP]",
    unknownToken: specialTokens.unk_token ?? "[UNK]",
  };
  tokenizer.unknownId = vocabulary.get(tokenizer.unknownToken);
  for (const required of [tokenizer.clsToken, tokenizer.sepToken, tokenizer.unknownToken]) {
    if (!vocabulary.has(required)) {
      throw new Error(`The tokenizer vocabulary does not contain required token: ${required}`);
    }
  }
  return tokenizer;
}

async function main() {
  const exportDirectory = getArgument("--export-dir");
  if (!exportDirectory) {
    throw new Error("Usage: node validate-node-onnx-candidate.mjs --export-dir <local-onnx-export-directory>");
  }
  const resolvedDirectory = path.resolve(exportDirectory);
  const fixture = JSON.parse(await fs.readFile(path.join(resolvedDirectory, "node_consistency_fixture.json"), "utf8"));
  const modelPath = path.join(resolvedDirectory, fixture.onnx_model);
  const tokenizer = await readTokenizer(resolvedDirectory, fixture.max_length);
  const lowMemoryMode = process.argv.includes("--low-memory");
  const sessionOptions = lowMemoryMode
    ? {
        executionProviders: ["cpu"],
        enableCpuMemArena: false,
        enableMemPattern: false,
        executionMode: "sequential",
        graphOptimizationLevel: "disabled",
        interOpNumThreads: 1,
        intraOpNumThreads: 1,
      }
    : { executionProviders: ["cpu"] };
  const beforeSessionMemory = memorySnapshot();
  const session = await ort.InferenceSession.create(modelPath, sessionOptions);
  const afterSessionMemory = memorySnapshot();
  const results = [];

  for (const sample of fixture.samples) {
    const inputIds = encode(sample.text, tokenizer);
    const attentionMask = new ort.Tensor("int64", BigInt64Array.from({ length: inputIds.size }, () => 1n), inputIds.dims);
    const tokenTypeIds = new ort.Tensor("int64", BigInt64Array.from({ length: inputIds.size }, () => 0n), inputIds.dims);
    const feeds = { input_ids: inputIds, attention_mask: attentionMask, token_type_ids: tokenTypeIds };
    const output = await session.run(feeds);
    const logits = [...output.logits.data].map(Number);
    const aiProbability = softmaxAiProbability(logits);
    const expected = Number(sample.onnx_ai_probability);
    const delta = Math.abs(aiProbability - expected);
    results.push({ id: sample.id, expected_ai_probability: expected, node_ai_probability: aiProbability, absolute_delta: delta });
  }

  const maximumDelta = Math.max(...results.map((result) => result.absolute_delta));
  const outcome = {
    schema_version: 1,
    status: maximumDelta < MAX_ALLOWED_PROBABILITY_DELTA ? "ok" : "failed",
    acceptance: { maximum_absolute_ai_probability_delta_lt: MAX_ALLOWED_PROBABILITY_DELTA },
    model_file: fixture.onnx_model,
    fixture_count: results.length,
    maximum_absolute_ai_probability_delta: maximumDelta,
    runtime: {
      node: process.version,
      onnxruntime_node: ort.version ?? "unknown",
      execution_provider: "cpu",
      low_memory_mode: lowMemoryMode,
    },
    memory_mb: { before_session: beforeSessionMemory, after_session: afterSessionMemory },
    samples: results,
  };
  process.stdout.write(`${JSON.stringify(outcome, null, 2)}\n`);
  if (outcome.status !== "ok") {
    process.exitCode = 1;
  }
}

main().catch((error) => {
  process.stderr.write(`${error.stack ?? error}\n`);
  process.exitCode = 1;
});
